    size 25mm x 20mm
    layers 2
}

// Power input - 2.54mm pitch header
component J1 connector "PIN-HDR-1x2" {
    at 5mm, 10mm
}

// Current limiting resistor for LED
// 5V - 2V(LED) = 3V, 3V/330R = ~9mA
